-- ========================================================================

-- Safety-critical flags for a Holter monitor result, independent of the axes.

CREATE TABLE holter_monitor_test_result_grade_flag (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    holter_monitor_test_result_grade_id UUID NOT NULL
        REFERENCES holter_monitor_test_result_grade(id) ON DELETE CASCADE,
    flag_id VARCHAR(50) NOT NULL,
    category VARCHAR(40) NOT NULL DEFAULT ''
        CHECK (category IN (
            'critical-result-alert',
            'incidental-finding',
            'discrepancy-with-request',
            'abnormal-requiring-action',
            'urgent-referral',
            'inadequate-recording',
            'unexpected-finding',
            'missing-impression',
            'missing-measurement',
            'other',
            ''
        )),
    priority VARCHAR(10) NOT NULL DEFAULT ''
        CHECK (priority IN ('low', 'medium', 'high', '')),
    description VARCHAR(500) NOT NULL DEFAULT '',
    suggested_action VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX index_holter_monitor_test_result_grade_flag_grade_id
    ON holter_monitor_test_result_grade_flag(holter_monitor_test_result_grade_id);

CREATE TRIGGER trigger_holter_monitor_test_result_grade_flag_updated_at
    BEFORE UPDATE ON holter_monitor_test_result_grade_flag
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE holter_monitor_test_result_grade_flag IS
    'Safety-critical flags that fire independently of the four axes, with priority and a suggested action for the reporting / referring team.';
COMMENT ON COLUMN holter_monitor_test_result_grade_flag.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN holter_monitor_test_result_grade_flag.created_at IS
    'Timestamp when this row was created.';
COMMENT ON COLUMN holter_monitor_test_result_grade_flag.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN holter_monitor_test_result_grade_flag.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
